 private void search(){((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(query.getWindowToken(),0);query.clearFocus();if(favoriteTab){render();return;}initialized=true;int token=++generation;if(task!=null)task.cancel(true);java.net.HttpURLConnection old=active;if(old!=null)old.disconnect();search.setEnabled(false);status.setText("Consultando rádios…");String term=query.getText().toString().trim();boolean brazil=region.getSelectedItemPosition()==0;final RadioCity selectedCity=city;task=worker.submit(()->{try{List<RadioStation> found=RadioDirectory.search(term,brazil,selectedCity,c->active=c);handler.post(()->{if(isDestroyed()||!started||token!=generation)return;catalog=found;RadioStore.cache(this,found,term,brazil);getSharedPreferences("radio",0).edit().putString("catalog_city",selectedCity==null?"":selectedCity.key()).apply();search.setEnabled(true);render();if(found.isEmpty())status.setText(selectedCity==null?"Nenhuma transmissão HTTPS encontrada. Tente outro nome ou selecione Todos os países.":"Nenhuma emissora HTTPS com coordenadas informadas até 50 km de "+selectedCity.name+". Tente sem cidade ou adicione o link da rádio.");});}catch(Exception e){handler.post(()->{if(isDestroyed()||!started||token!=generation)return;search.setEnabled(true);status.setText("Não foi possível consultar o catálogo agora. Suas rádios salvas continuam disponíveis.");});}});}
