 private List<RadioCity> localCities(String term)throws Exception{try(java.io.InputStream in=getAssets().open("radio-cities-br.json");java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedException();if(out.size()+n>1024*1024)throw new java.io.IOException("Base de cidades inválida.");out.write(b,0,n);}return RadioCity.local(out.toString("UTF-8"),term);}}
