 private void applyCity(RadioCity selected){SharedPreferences prefs=getSharedPreferences("radio",0);try{SharedPreferences.Editor edit=prefs.edit();if(selected==null)edit.remove("city");else edit.putString("city",selected.json().toString());edit.apply();}catch(org.json.JSONException e){return;}city=selected;updateCityButton();String key=selected==null?"":selected.key();boolean matches=prefs.getString("catalog_city","").equals(key)&&prefs.getString("query","").equals(query.getText().toString().trim())&&(selected!=null||prefs.getBoolean("brazil",true)==(region.getSelectedItemPosition()==0));List<RadioStation> cached=matches?RadioStore.cached(this):Collections.emptyList();catalog.clear();if(cityDialog!=null)cityDialog.dismiss();if(!cached.isEmpty()){catalog=new ArrayList<>(cached);initialized=true;render();}else{render();search();}}
 private void stopCityLookup(){cityGeneration++;if(cityTask!=null)cityTask.cancel(true);}
