 private void lookupCity(){String term=cityInput.getText().toString().trim();if(term.isEmpty()){cityInput.setError("Digite uma cidade.");return;}((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(cityInput.getWindowToken(),0);cityInput.clearFocus();stopCityLookup();int token=cityGeneration;boolean brazil=region.getSelectedItemPosition()==0;String key="BR:"+SearchText.normalize(term);SharedPreferences prefs=getSharedPreferences("radio",0);if(key.equals(prefs.getString("city_lookup_query",""))){List<RadioCity> cached=RadioCity.read(prefs.getString("city_lookup_results","[]"));if(!cached.isEmpty()){cityRows(cached);cityStatus.setText("Escolha a cidade encontrada.");return;}}cityStatus.setText("Buscando cidades…");cityTask=cityWorker.submit(()->{try{List<RadioCity> found=localCities(term);handler.post(()->{if(!started||isDestroyed()||token!=cityGeneration||cityDialog==null||!cityDialog.isShowing())return;prefs.edit().putString("city_last_text",term).putString("city_lookup_query",key).putString("city_lookup_results",RadioCity.write(found)).apply();cityRows(found);cityStatus.setText(found.isEmpty()?"Cidade não encontrada. Inclua o estado ou país e tente novamente.":"Escolha a cidade. Serão buscadas emissoras até 50 km, conforme os dados informados no catálogo.");});}catch(Exception e){handler.post(()->{if(started&&!isDestroyed()&&token==cityGeneration&&cityDialog!=null&&cityDialog.isShowing())cityStatus.setText("Não foi possível consultar as cidades agora. Tente novamente. A pesquisa por país e suas favoritas continuam disponíveis.");});}});}
 @Override protected void onStart(){super.onStart();started=true;if(query!=null){render();updatePlayer();if(!initialized&&!favoriteTab)search();}}
 @Override protected void onStop(){started=false;stopCityLookup();generation++;if(task!=null)task.cancel(true);java.net.HttpURLConnection old=active;if(old!=null)old.disconnect();if(search!=null)search.setEnabled(true);super.onStop();}
 @Override protected void onDestroy(){stopCityLookup();cityWorker.shutdownNow();if(cityDialog!=null)cityDialog.dismiss();generation++;if(task!=null)task.cancel(true);java.net.HttpURLConnection old=active;if(old!=null)old.disconnect();worker.shutdownNow();handler.removeCallbacksAndMessages(null);if(addDialog!=null)addDialog.dismiss();if(sourcesDialog!=null)sourcesDialog.dismiss();if(connection!=null)MediaController.releaseFuture(connection);super.onDestroy();}
